function getNextPositiveFeedback() {
  const index = positiveFeedbackRotationIndex % POSITIVE_ANSWER_FEEDBACK.length;
  positiveFeedbackRotationIndex += 1;
  return POSITIVE_ANSWER_FEEDBACK[index];
}

function getNextNegativeFeedback() {
  const index = negativeFeedbackRotationIndex % NEGATIVE_ANSWER_FEEDBACK.length;
  negativeFeedbackRotationIndex += 1;
  return NEGATIVE_ANSWER_FEEDBACK[index];
}

function showAnswerFeedback(message = "", tone = "good") {
  if (!answerFeedbackEl) return;
  const text = String(message || "").trim();
  if (!text) {
    answerFeedbackEl.classList.add("hidden");
    answerFeedbackEl.classList.remove("show", "tone-good", "tone-bad", "tone-info");
    answerFeedbackEl.textContent = "";
    return;
  }
  answerFeedbackEl.textContent = text;
  answerFeedbackEl.classList.remove("hidden", "show", "tone-good", "tone-bad", "tone-info");
  answerFeedbackEl.classList.add(
    tone === "bad" ? "tone-bad" : tone === "info" ? "tone-info" : "tone-good",
  );
  void answerFeedbackEl.offsetWidth;
  answerFeedbackEl.classList.add("show");
  if (answerFeedbackHideTimer) {
    clearTimeout(answerFeedbackHideTimer);
  }
  answerFeedbackHideTimer = setTimeout(() => {
    answerFeedbackEl.classList.add("hidden");
    answerFeedbackEl.classList.remove("show", "tone-good", "tone-bad", "tone-info");
    answerFeedbackHideTimer = null;
  }, ANSWER_FEEDBACK_VISIBLE_MS);
}

function clearAnswerChoiceMotivation() {
  if (!answersEl) return;
  answersEl.querySelectorAll(".answer-choice-motivation").forEach((node) => node.remove());
  answersEl.querySelectorAll("button.has-answer-choice-motivation").forEach((btn) => {
    btn.classList.remove("has-answer-choice-motivation");
  });
  if (answerChoiceMotivationHideTimer) {
    clearTimeout(answerChoiceMotivationHideTimer);
    answerChoiceMotivationHideTimer = null;
  }
}

function showAnswerChoiceMotivation(choiceValue, isCorrect) {
  if (!answersEl) return;
  const value = String(choiceValue || "").trim();
  if (!value) return;

  const selectedButton = Array.from(answersEl.querySelectorAll("button")).find(
    (btn) => String(btn?.dataset?.value || "").trim() === value,
  );
  if (!selectedButton) return;

  clearAnswerChoiceMotivation();

  const text = isCorrect ? getNextPositiveFeedback() : getNextNegativeFeedback();
  if (!text) return;

  const badge = document.createElement("span");
  badge.className = `answer-choice-motivation ${isCorrect ? "tone-good" : "tone-bad"}`;
  badge.textContent = text;
  badge.setAttribute("aria-label", text);

  selectedButton.classList.add("has-answer-choice-motivation");
  selectedButton.appendChild(badge);

  answerChoiceMotivationHideTimer = setTimeout(() => {
    clearAnswerChoiceMotivation();
  }, ANSWER_CHOICE_MOTIVATION_VISIBLE_MS);
}

function shouldShowAnswerChoiceMotivation() {
  if (mode === "daily" || mode === "smart") return false;
  if (mode === "exam") {
    const variant = String(examVariant || "normal").toLowerCase();
    return variant === "rapid" || variant === "sudden" || variant === "clinical";
  }
  return isStudyLikeMode();
}

function isDirectSubmitDrillMode() {
  if (mode !== "exam") return false;
  const variant = String(examVariant || "normal").toLowerCase();
  return variant === "rapid" || variant === "sudden" || variant === "clinical" || variant === "law";
}

