document.addEventListener("click", (event) => {
  if (!menuUserHubPanel || menuUserHubPanel.classList.contains("hidden")) return;
  const target = event.target;
  if (!(target instanceof Node)) return;
  if (menuUserHubPanel.contains(target)) return;
  if (menuUserHubBtn && menuUserHubBtn.contains(target)) return;
  if (menuMobileHamburgerBtn && menuMobileHamburgerBtn.contains(target)) return;
  closeMenuUserHub();
});

function setAuthPasswordVisibility(visible) {
  if (!authPasswordInput || !authPasswordToggleBtn) return;
  const show = Boolean(visible);
  authPasswordInput.type = show ? "text" : "password";
  authPasswordToggleBtn.setAttribute(
    "aria-label",
    show ? "Hide password" : "Show password",
  );
  authPasswordToggleBtn.setAttribute("aria-pressed", show ? "true" : "false");

  const eyeIcon = authPasswordToggleBtn.querySelector(".icon-eye");
  const eyeOffIcon = authPasswordToggleBtn.querySelector(".icon-eye-off");
  if (eyeIcon) eyeIcon.classList.toggle("hidden", show);
  if (eyeOffIcon) eyeOffIcon.classList.toggle("hidden", !show);
}

function toggleAuthPasswordVisibility() {
  if (!authPasswordInput) return;
  setAuthPasswordVisibility(authPasswordInput.type === "password");
}

function normalizeTopicPathToken(value) {
  const token = String(value || "")
    .trim()
    .toLowerCase()
    .replace(/_/g, "-")
    .replace(/\s+/g, "-");
  return /^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(token) ? token : "";
}

const TOPIC_NOTE_BUILD_ID = "20260325-topicnote8";

function withTopicNoteVersion(url = "") {
  const raw = String(url || "").trim();
  if (!raw) return "";
  const hashIndex = raw.indexOf("#");
  const base = hashIndex >= 0 ? raw.slice(0, hashIndex) : raw;
  const hash = hashIndex >= 0 ? raw.slice(hashIndex) : "";
  const joiner = base.includes("?") ? "&" : "?";
  return `${base}${joiner}v=${TOPIC_NOTE_BUILD_ID}${hash}`;
}

function buildTopicUrl(question) {
  const slug = normalizeTopicPathToken(question?.topicSlug);
  if (!slug) return "";

  const sectionId = normalizeTopicPathToken(question?.sectionId);
  const hash = sectionId ? `#${sectionId}` : "";
  return withTopicNoteVersion(`topics/${slug}.html${hash}`);
}

function renderQuestionTopicLink(question) {
  if (!topicLinkWrapEl || !topicLinkBtnEl) return;

  const isStudyMode = isStudyLikeMode();
  if (!isStudyMode || isLawStudyMode()) {
    topicLinkWrapEl.classList.add("hidden");
    topicLinkBtnEl.removeAttribute("href");
    return;
  }

  const url = buildTopicUrl(question);
  if (!url) {
    topicLinkWrapEl.classList.add("hidden");
    topicLinkBtnEl.removeAttribute("href");
    return;
  }

  topicLinkBtnEl.href = url;
  topicLinkWrapEl.classList.remove("hidden");
}

function getQuestionOptionKeys(question) {
  if (question?.type === "combo") {
    return ["A", "B", "C", "D", "E"];
  }
  if (Array.isArray(question?.options)) {
    return question.options.map((option) => String(option || "").trim()).filter(Boolean);
  }
  return [];
}

function getWrongOptionReason(question, optionKey) {
  const option = String(optionKey || "").trim();
  if (!option) return "";
  const map =
    question?.wrongOptionExplanations &&
    typeof question.wrongOptionExplanations === "object"
      ? question.wrongOptionExplanations
      : {};
  const explicit = String(map[option] || "").trim();
  return explicit;
}

function escapeHtml(value) {
  return String(value || "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

function formatExplanationTextForHtml(value) {
  return escapeHtml(value).replace(/\n/g, "<br>");
}

function getQuestionExplanationSections(question) {
  const q = question && typeof question === "object" ? question : {};
  const sections = {
    base: "",
    explainCorrect: "",
    wrongLines: [],
  };

  const base = String(q.explanation || "").trim();
  if (base) {
    sections.base = base;
  }

  const explainCorrect = String(q.explainCorrect || "").trim();
  if (explainCorrect) {
    sections.explainCorrect = explainCorrect;
  }

  const optionKeys = getQuestionOptionKeys(q);
  const correct = String(q.correct || "").trim();
  sections.wrongLines = optionKeys
    .filter((optionKey) => String(optionKey || "").trim() !== correct)
    .map((optionKey) => {
      const reason = getWrongOptionReason(q, optionKey);
      if (!reason) return "";
      return `${optionKey}: ${reason}`;
    })
    .filter(Boolean);

  return sections;
}

function renderQuestionExplanation(question) {
  if (!explanationEl) return;
  const sections = getQuestionExplanationSections(question);
  const hasContent =
    Boolean(sections.base) ||
    Boolean(sections.explainCorrect) ||
    (Array.isArray(sections.wrongLines) && sections.wrongLines.length > 0);

  if (!hasContent) {
    explanationEl.classList.add("hidden");
    explanationEl.innerHTML = "";
    return;
  }

  const blocks = [];
  if (sections.base) {
    blocks.push(
      `<section class="explain-section explain-main"><h4 class="explain-label">Explanation</h4><div class="explain-body">${formatExplanationTextForHtml(sections.base)}</div></section>`,
    );
  }

  if (sections.explainCorrect) {
    blocks.push(
      `<section class="explain-section explain-correct"><h4 class="explain-label">Why Correct</h4><div class="explain-body">${formatExplanationTextForHtml(sections.explainCorrect)}</div></section>`,
    );
  }

  if (Array.isArray(sections.wrongLines) && sections.wrongLines.length > 0) {
    const items = sections.wrongLines
      .map((line) => {
        const splitAt = line.indexOf(":");
        if (splitAt <= 0) {
          return `<li class="explain-item">${formatExplanationTextForHtml(line)}</li>`;
        }
        const option = line.slice(0, splitAt).trim();
        const reason = line.slice(splitAt + 1).trim();
        return `<li class="explain-item"><span class="explain-option">${escapeHtml(option)}:</span> ${formatExplanationTextForHtml(reason)}</li>`;
      })
      .join("");
    blocks.push(
      `<section class="explain-section explain-wrong"><h4 class="explain-label">Why Others Are Wrong</h4><ul class="explain-list">${items}</ul></section>`,
    );
  }

  explanationEl.innerHTML = blocks.join("");
  explanationEl.classList.remove("hidden");
}

function resetMemoryTrickBox() {
  if (!memoryTrickBoxEl) return;
  memoryTrickBoxEl.classList.add("hidden");
  memoryTrickBoxEl.textContent = "";
}

function setMemoryTrickLoading() {
  if (!memoryTrickBoxEl) return;
  memoryTrickBoxEl.classList.remove("hidden");
  memoryTrickBoxEl.textContent = "Memory trick: loading...";
}

function canShowPeerInsight() {
  return isStudyLikeMode() || inReview || inDetailedReview;
}

function clearOptionPeerBadges() {
  if (!answersEl) return;
  answersEl.querySelectorAll(".peer-choice-badge").forEach((node) => node.remove());
  answersEl.querySelectorAll("button.has-peer-badge").forEach((btn) => {
    btn.classList.remove("has-peer-badge");
  });
  clearAnswerChoiceMotivation();
}

function renderPeerChoiceBadges(data) {
  clearOptionPeerBadges();
  return;
}

function renderMemoryTrickForQuestion(question, data) {
  if (!memoryTrickBoxEl) return;
  const serverText = String(data?.memoryTrick || "").trim();
  const localText = String(question?.memoryTrick || "").trim();
  const text = localText || serverText;

  if (!text) {
    resetMemoryTrickBox();
    return;
  }

  memoryTrickBoxEl.classList.remove("hidden");
  memoryTrickBoxEl.textContent = `Memory trick: ${text}`;
}

async function loadAnswerInsightForQuestion(question) {
  if (!canShowPeerInsight()) {
    clearOptionPeerBadges();
    resetMemoryTrickBox();
    return;
  }

  const key = normalizeQuestionIdKey(question?.id);
  if (!key) {
    clearOptionPeerBadges();
    resetMemoryTrickBox();
    return;
  }

  if (questionInsightCache[key]) {
    renderPeerChoiceBadges(questionInsightCache[key]);
    renderMemoryTrickForQuestion(question, questionInsightCache[key]);
    return;
  }

  if (questionInsightInFlightKey === key) return;

  questionInsightInFlightKey = key;
  setMemoryTrickLoading();

  try {
    const data = await backendClient.fetchQuestionInsights(Number(key));
    questionInsightCache[key] = data;
    if (
      Array.isArray(active) &&
      active[current] &&
      normalizeQuestionIdKey(active[current].id) === key
    ) {
      renderPeerChoiceBadges(data);
      renderMemoryTrickForQuestion(question, data);
    }
  } catch {
    clearOptionPeerBadges();
    renderMemoryTrickForQuestion(question, null);
  } finally {
    if (questionInsightInFlightKey === key) {
      questionInsightInFlightKey = "";
    }
  }
}

function prettifyTopicSlug(slug) {
  return String(slug || "")
    .split("-")
    .filter(Boolean)
    .map((word) => word.charAt(0).toUpperCase() + word.slice(1))
    .join(" ");
}

function normalizeTopicNotePath(pathValue) {
  const raw = String(pathValue || "").trim().toLowerCase();
  if (!raw) return "";
  if (!/^[a-z0-9-]+\.html(?:#[a-z0-9-]+)?$/.test(raw)) return "";
  return `topics/${raw}`;
}

function topicSearchText(topic) {
  const sectionTitles = Array.isArray(topic?.sections)
    ? topic.sections.map((section) => section.title || "")
    : [];
  return [
    topic?.title,
    topic?.slug,
    topic?.summary,
    topic?.category,
    ...(Array.isArray(topic?.tags) ? topic.tags : []),
    ...sectionTitles,
  ]
    .join(" ")
    .toLowerCase();
}

function topicTitle(topic) {
  return (
    String(topic?.title || "").trim() ||
    prettifyTopicSlug(topic?.slug) ||
    "Study Note"
  );
}

function getFilteredTopicsForLibrary() {
  const rawTopics = Array.isArray(topicCatalog?.topics) ? topicCatalog.topics : [];
  const category = String(topicLibraryCategorySelect?.value || "all");
  const search = String(topicLibrarySearchInput?.value || "").trim().toLowerCase();

  return rawTopics
    .filter((topic) => {
      if (category !== "all" && topic.category !== category) {
        return false;
      }
      if (!search) return true;
      return topicSearchText(topic).includes(search);
    })
    .sort((a, b) => topicTitle(a).localeCompare(topicTitle(b)));
}

function renderTopicLibrary() {
  if (!topicLibraryListEl || !topicLibraryEmptyEl || !topicLibraryCountEl) return;

  const filteredTopics = getFilteredTopicsForLibrary();
  topicLibraryListEl.innerHTML = "";

  filteredTopics.forEach((topic) => {
    const notePath =
      normalizeTopicNotePath(topic.notePath) ||
      normalizeTopicNotePath(`${String(topic.slug || "").toLowerCase()}.html`);
    if (!notePath) return;

    const item = document.createElement("div");
    item.className = "topic-library-item";
    item.innerHTML = `
      <button type="button" class="topic-library-item-link">
        <span class="topic-library-item-copy">
          <span class="topic-library-item-title">${topicTitle(topic)}</span>
        </span>
        <span class="topic-library-item-arrow" aria-hidden="true">&#8250;</span>
      </button>
    `;
    const openBtn = item.querySelector(".topic-library-item-link");
    openBtn?.addEventListener("click", () => {
      openTopicViewer(notePath, topicTitle(topic), "topic-library", topic.category || "");
    });
    topicLibraryListEl.appendChild(item);
  });

  topicLibraryCountEl.textContent = `${filteredTopics.length} topic${filteredTopics.length === 1 ? "" : "s"} available`;
  topicLibraryEmptyEl.classList.toggle("hidden", filteredTopics.length > 0);
}

function populateTopicLibraryCategories() {
  if (!topicLibraryCategorySelect) return;

  topicLibraryCategorySelect.innerHTML = '<option value="all">All Categories</option>';
  MAJOR_CATEGORIES.forEach((category) => {
    const option = document.createElement("option");
    option.value = category;
    option.innerText = category;
    topicLibraryCategorySelect.appendChild(option);
  });
  syncSetupPickerButton(topicLibraryCategorySelect, topicLibraryCategoryPickerBtn);
}

async function ensureTopicCatalogLoaded() {
  if (topicCatalogLoaded) return;

  try {
    const response = await fetch("topics/topics.json", { cache: "no-store" });
    if (!response.ok) {
      throw new Error(`topics.json failed (${response.status})`);
    }
    topicCatalog = await response.json();
  } catch (error) {
    console.warn("Topic catalog fallback enabled:", error);
    topicCatalog = {
      topics: [
        {
          slug: "heart-failure",
          title: "Heart Failure",
          category: "Cardiovascular Disorders",
          summary:
            "HFrEF/HFpEF classification, four-pillar HFrEF therapy, and acute decompensation.",
          notePath: "heart-failure.html",
        },
        {
          slug: "hypertension",
          title: "Hypertension",
          category: "Cardiovascular Disorders",
          summary:
            "Blood pressure classification, first-line treatment, and hypertensive crisis.",
          notePath: "hypertension.html",
        },
      ],
      categories: [...MAJOR_CATEGORIES],
    };
  } finally {
    topicCatalogLoaded = true;
    renderTopicLibrary();
  }
}

function openTopicLibrary(returnScreen = "quiz-menu") {
  topicLibraryReturnScreen = returnScreen;
  showScreen("topic-library");
  ensureTopicCatalogLoaded();
  renderTopicLibrary();
}

