function updateModeIndicator(studyType = null) {
  const indicator = document.getElementById("mode-indicator");
  const headerStats = document.getElementById("header-stats");
  const timerEl = document.getElementById("timer");

  if (!indicator) return;
  if (quizArea) {
    quizArea.classList.remove(
      "mode-study",
      "mode-topic",
      "mode-exam",
      "mode-smart",
      "mode-daily",
      "mode-law",
      "mode-rapid",
      "mode-sudden",
      "mode-clinical",
    );
  }

  if (mode === "study") {
    const resolvedStudyType = String(studyType || getCurrentStudyType()).trim().toLowerCase();
    const lawDrillActive = isLawStudyMode();
    if (lawDrillActive) {
      indicator.innerText = "Law Drill";
    } else if (resolvedStudyType === "weak") {
      indicator.innerText = "📚 Practice Weak Areas";
    } else {
      indicator.innerText = "📚 Study Mode";
    }

    indicator.innerText =
      lawDrillActive
        ? "Law Drill"
        : resolvedStudyType === "weak"
          ? "Practice Weak Areas"
          : "Study Mode";
    if (headerStats) headerStats.style.display = "flex";
    if (timerEl) timerEl.classList.add("hidden");
    if (quizArea) quizArea.classList.add("mode-study");
    if (lawDrillActive && quizArea) quizArea.classList.add("mode-law");
    if (lawDrillActive && headerInlineMeta) {
      headerInlineMeta.innerHTML = renderLawDrillInlineMeta();
      headerInlineMeta.classList.remove("hidden");
    }
  } else if (mode === "topic") {
    indicator.innerText = `${getTopicQuizSessionTitle()} Quiz`;
    if (headerStats) headerStats.style.display = "none";
    if (timerEl) timerEl.classList.add("hidden");
    if (quizArea) quizArea.classList.add("mode-topic");
  } else if (mode === "exam") {
    indicator.innerText =
      examVariant === "rapid"
        ? "Rapid Drill"
        : examVariant === "sudden"
          ? "Sudden Drill"
          : examVariant === "clinical"
            ? "Clinical Drill"
            : examVariant === "law"
              ? "Pharmacy Law"
            : "Exam Mode";
    if (headerStats) headerStats.style.display = "none";
    if (timerEl) {
      if (examVariant === "sudden" || examVariant === "clinical") {
        timerEl.classList.add("hidden");
      } else {
        timerEl.classList.remove("hidden");
      }
    }
    if (quizArea) {
      quizArea.classList.add("mode-exam");
      if (examVariant === "rapid") quizArea.classList.add("mode-rapid");
      if (examVariant === "sudden") quizArea.classList.add("mode-sudden");
      if (examVariant === "clinical") quizArea.classList.add("mode-clinical");
    }
  } else if (mode === "smart") {
    indicator.innerText = "Smart Exam";

    if (headerStats) headerStats.style.display = "none";
    if (timerEl) timerEl.classList.remove("hidden");
    if (quizArea) quizArea.classList.add("mode-smart");
  } else if (mode === "daily") {
    indicator.innerText = "Daily Quiz";

    if (headerStats) headerStats.style.display = "none";
    if (timerEl) timerEl.classList.add("hidden");
    if (quizArea) quizArea.classList.add("mode-daily");
  }

  if (headerInlineMeta) {
    const compactHeaderMode =
      mode === "topic" ||
      mode === "daily" ||
      mode === "smart" ||
      (mode === "exam" &&
        ["normal", "rapid", "sudden", "clinical"].includes(String(examVariant || "normal"))) ||
      (mode === "study" && isLawStudyMode());
    headerInlineMeta.classList.toggle("hidden", !compactHeaderMode);
    if (!compactHeaderMode) headerInlineMeta.innerHTML = "";
  }
}
