window.addEventListener("load", function () {
  const pendingTopicQuizLaunch = hasPendingTopicQuizLaunch();
  setAuthMode("login");
  profileImageMarkedForDeletion = false;
  setProfileAvatarPreview("");
  updateProfileButtonAvatar("");
  refreshProfilePhotoDeleteVisibility();
  renderAuthState();
  restoreAuthSession();
  closeCommunityConversationActions();
  closeCommunityFriendActions();
  window.setTimeout(() => {
    void checkForNativeAppUpdate();
  }, 900);

  if (pendingTopicQuizLaunch) {
    consumePendingTopicQuizLaunch();
  }

  renderModeHistory("Study", "study-history");
  renderModeHistory("Exam", "exam-history");

  const abandoned = localStorage.getItem("examAbandoned");

  if (abandoned) {
    localStorage.removeItem("examAbandoned");

    const saved = JSON.parse(localStorage.getItem("quizExamSession"));

    if (saved) {
      const savedMode = String(saved.mode || "exam");
      const savedVariant =
        savedMode === "smart"
          ? "smart"
          : String(saved.examVariant || "normal").toLowerCase();
      const resumableDrill =
        savedMode === "exam" && (savedVariant === "sudden" || savedVariant === "clinical");

      if (!resumableDrill) {
        active = saved.active;
        userAnswers = saved.userAnswers || {};
        mode = savedMode;
        if (mode !== "exam" && mode !== "smart") {
          mode = "exam";
        }
        examVariant = savedVariant;
        examTimeBudget = Math.max(
          0,
          Number(saved.examTimeBudget) ||
            (Array.isArray(saved.active) ? saved.active.length * 40 : 40),
        );
        suddenMilestoneLevel = Math.max(0, Number(saved.suddenMilestoneLevel) || 0);
        clinicalLives = Math.max(0, Number(saved.clinicalLives) || 3);

        // Non-drill abandoned exams still auto-finish on reload.
        finishExam();
        return;
      }
    }

    const homeTotalQuestions = document.getElementById("home-total-questions");
    const homeTotalSessions = document.getElementById("home-total-sessions");
    const homeBestStreak = document.getElementById("home-best-streak");

    if (homeTotalQuestions) {
      homeTotalQuestions.innerText = questionBank.length;
    }

    if (homeTotalSessions) {
      homeTotalSessions.innerText = sessionHistory.length;
    }

    if (homeBestStreak) {
      homeBestStreak.innerText = localStorage.getItem("quizBestStreak") || 0;
    }
  }

  if (!pendingTopicQuizLaunch) {
    if (shouldShowWelcomeIntro()) {
      markWelcomeIntroSeen();
      showScreen("welcome-screen", { recordHistory: false });
    } else {
      showScreen("home-screen", { recordHistory: false });
    }
  }

  const runDeferredBootstrap = () => {
    wireSetupPickerModal();
    wireSetupPickerTriggers();
    refreshQuestionDependentUi();
    void loadQuestionsFromBackend();
    backendClient.warmup().catch(() => {
      // Keep local-first behavior if backend is offline.
    });
  };

  if (typeof window.requestIdleCallback === "function") {
    window.requestIdleCallback(runDeferredBootstrap, { timeout: 1500 });
  } else {
    window.setTimeout(runDeferredBootstrap, 0);
  }
});

