function shuffle(array) {
  for (let i = array.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [array[i], array[j]] = [array[j], array[i]];
  }
  return array;
}

document.addEventListener("keydown", function (e) {
  if (appUpdateModalEl && !appUpdateModalEl.classList.contains("hidden") && e.key === "Escape") {
    if (!Boolean(appUpdateCurrentPayload?.forceUpdate)) {
      closeAppUpdateModal();
    }
    return;
  }
  if (communityReportModalEl && !communityReportModalEl.classList.contains("hidden") && e.key === "Escape") {
    closeCommunityReportModal();
    return;
  }
  if (authModal && !authModal.classList.contains("hidden") && e.key === "Escape") {
    closeAuthModal();
    return;
  }
  if (communityLockResetModalEl && !communityLockResetModalEl.classList.contains("hidden") && e.key === "Escape") {
    closeCommunityLockResetModal();
    return;
  }
  if (communityLockModalEl && !communityLockModalEl.classList.contains("hidden") && e.key === "Escape") {
    closeCommunityLockModal({ unlocked: false });
    return;
  }
  if (globalQuickNavEl && !globalQuickNavEl.classList.contains("hidden") && e.key === "Escape") {
    closeGlobalQuickNav({ restoreFocus: true });
    return;
  }
  if (menuUserHubPanel && !menuUserHubPanel.classList.contains("hidden") && e.key === "Escape") {
    closeMenuUserHub();
    return;
  }
  if (!examExitModal.classList.contains("hidden") && e.key === "Escape") {
    closeExamExitModal();
  }
  if (!studyExitModal.classList.contains("hidden") && e.key === "Escape") {
    closeStudyExitModal();
  }
  if (sessionResumeModal && !sessionResumeModal.classList.contains("hidden") && e.key === "Escape") {
    closeSessionResumeModal();
  }
});

